// Split the reading into short TTS-sized segments (one n8n item each).
const raw = String($json.readingText || '').trim();
if (!raw || raw.startsWith('Paste the full')) throw new Error('Paste the real reading text into 2 · TEST INPUTS (readingText).');
const voiceReferenceUrl = $json.voiceReferenceUrl;
const voiceVersion = $json.voiceVersion || '';
if (!voiceReferenceUrl || voiceReferenceUrl.includes('REPLACE-ME')) throw new Error('Set voiceReferenceUrl to a PUBLIC Marcus voice sample URL.');

const MAX = 600; // chars per segment — keeps each Chatterbox call short
const paras = raw.split(/\n\s*\n/).map(s => s.replace(/\s+/g, ' ').trim()).filter(Boolean);

// Pack paragraphs into <= MAX chunks
const packed = [];
let buf = '';
for (const p of paras) {
  if (buf && (buf + ' ' + p).length > MAX) { packed.push(buf.trim()); buf = p; }
  else { buf = buf ? buf + ' ' + p : p; }
}
if (buf.trim()) packed.push(buf.trim());

// Hard-split any single chunk still over MAX, by sentence
const final = [];
for (const chunk of packed) {
  if (chunk.length <= MAX) { final.push(chunk); continue; }
  const sents = chunk.match(/[^.!?]+[.!?]*/g) || [chunk];
  let b = '';
  for (const s of sents) {
    if (b && (b + ' ' + s).length > MAX) { final.push(b.trim()); b = s; }
    else { b = b ? b + ' ' + s : s; }
  }
  if (b.trim()) final.push(b.trim());
}

if (!final.length) throw new Error('No segments produced from readingText.');
return final.map((text, i) => ({ json: { index: i + 1, total: final.length, text, voiceReferenceUrl, voiceVersion } }));

// Pull the finished audio URL out of each Replicate prediction, keep it tied to its segment.
const seg = $('3 · Split reading into segments').item.json;
const p = $json;
let audioUrl = null;
if (typeof p.output === 'string') audioUrl = p.output;
else if (Array.isArray(p.output)) audioUrl = p.output[0] || null;
else if (p.output && typeof p.output === 'object') audioUrl = p.output.audio || p.output.audio_out || p.output.output || null;
return [{ json: {
  index: seg.index,
  total: seg.total,
  status: p.status,
  predictionId: p.id || null,
  audioUrl,
  textPreview: String(seg.text || '').slice(0, 90)
} }];

// Collapse all segments into one ordered result you can read/download.
const rows = $input.all().map(i => i.json).sort((a, b) => a.index - b.index);
const allDone = rows.length > 0 && rows.every(r => r.status === 'succeeded' && r.audioUrl);
const notDone = rows.filter(r => !(r.status === 'succeeded' && r.audioUrl)).map(r => r.index);
return [{ json: {
  segmentCount: rows.length,
  allSucceeded: allDone,
  segmentsNeedingRetry: notDone,
  audioUrls: rows.map(r => r.audioUrl),
  segments: rows
} }];
